import java.util.LinkedHashSet;
import java.util.SequencedSet;

public class SequencedDemo {
    public static void main(String[] args) {
        SequencedSet<String> languages = new LinkedHashSet<>();

        languages.add("Java");
        languages.add("Python");
        languages.add("Rust");

        // Uniform access regardless of concrete type
        System.out.println("First: " + languages.getFirst()); // Java
        System.out.println("Last: " + languages.getLast());   // Rust

        // Add to the front of the set
        languages.addFirst("TypeScript");

        // Zero-copy reverse view iteration
        SequencedSet<String> reversed = languages.reversed();
        System.out.println("Reversed: " + reversed);
    }
}
